Try each possible first number from shortest to longest (shorter means smaller without leading zeros); once the first number is fixed every later number is forced, so recursively check that the remaining text spells successive increments.
```python
from typing import Optional


def consecutive_number_split(s: str) -> list[int]:
    def follow(i: int, prev: int) -> Optional[list[int]]:
        if i == len(s):
            return []
        nxt = str(prev + 1)
        if not s.startswith(nxt, i):
            return None
        rest = follow(i + len(nxt), prev + 1)
        return None if rest is None else [prev + 1] + rest

    for length in range(1, len(s)):
        piece = s[:length]
        if length > 1 and piece[0] == '0':
            break
        first = int(piece)
        rest = follow(length, first)
        if rest is not None:
            return [first] + rest
    return []
```

Accumulate words into the current line while the line plus a space plus the next word still fits; otherwise flush the line and start a new one with that word.
```python
from typing import List


def wrap_words_to_width(text: str, width: int) -> List[str]:
    lines: List[str] = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
```

Use four states (field start, unquoted, inside quotes, just-saw-a-quote-inside-quotes); the last state disambiguates an escaped doubled quote from the closing quote, and the final buffer is always flushed as the last field.
```python
def parse_csv_record(line: str) -> list[str]:
    fields = []
    buf = []
    state = "start"  # start | unquoted | quoted | quote_in_quoted
    for ch in line:
        if state == "start":
            if ch == '"':
                state = "quoted"
            elif ch == ",":
                fields.append("")
            else:
                buf.append(ch)
                state = "unquoted"
        elif state == "unquoted":
            if ch == ",":
                fields.append("".join(buf))
                buf = []
                state = "start"
            else:
                buf.append(ch)
        elif state == "quoted":
            if ch == '"':
                state = "quote_in_quoted"
            else:
                buf.append(ch)
        else:  # just saw a quote inside a quoted field
            if ch == '"':
                buf.append('"')
                state = "quoted"
            elif ch == ",":
                fields.append("".join(buf))
                buf = []
                state = "start"
            else:
                buf.append(ch)
                state = "unquoted"
    fields.append("".join(buf))
    return fields
```

Values are all distinct exactly when collapsing them into a set loses nothing, so compare the set size with the dict size.
```python
def all_values_distinct(d: dict) -> bool:
    return len(set(d.values())) == len(d)
```

If n is already a single digit it is the answer; otherwise recurse on the sum of its digits, which shrinks the number rapidly.
```python
def repeated_digit_sum(n: int) -> int:
    if n < 10:
        return n
    return repeated_digit_sum(sum(int(d) for d in str(n)))
```

Zip the digit list with itself shifted by one and take the maximum absolute difference, using default=0 for single-digit inputs.
```python
def max_adjacent_digit_gap(n: int) -> int:
    digits = [int(ch) for ch in str(abs(n))]
    return max((abs(a - b) for a, b in zip(digits, digits[1:])), default=0)
```

Track the alternating run ending at each index, extending it when parity flips and resetting to 1 otherwise.
```python
from typing import List


def longest_alternating_parity_run(nums: List[int]) -> int:
    best = cur = 0
    for i, x in enumerate(nums):
        if i > 0 and (x - nums[i - 1]) % 2 == 1:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best
```

Skip points on an axis, then classify the rest by the signs of x and y into one of four counters.
```python
from typing import List, Tuple


def quadrant_point_counts(points: List[Tuple[int, int]]) -> Tuple[int, int, int, int]:
    counts = [0, 0, 0, 0]
    for x, y in points:
        if x == 0 or y == 0:
            continue
        if y > 0:
            counts[0 if x > 0 else 1] += 1
        else:
            counts[3 if x > 0 else 2] += 1
    return tuple(counts)
```

Horner's rule: map each character to its digit value, reject anything out of range for the base, and accumulate value = value * base + digit.
```python
def parse_base_digits(s: str, base: int) -> int:
    if not s:
        return -1
    value = 0
    for ch in s.upper():
        if "0" <= ch <= "9":
            digit = ord(ch) - ord("0")
        elif "A" <= ch <= "Z":
            digit = ord(ch) - ord("A") + 10
        else:
            return -1
        if digit >= base:
            return -1
        value = value * base + digit
    return value
```

This is Dijkstra's shunting-yard algorithm: operands go straight to output, and an operator first pops stacked operators of higher precedence, or of equal precedence when left associative. An expect_operand flag tracks whether an operand or an operator should come next, which catches malformed sequences, and leftover '(' on the stack means unbalanced input.
```python
import re


def infix_to_postfix(expression: str) -> str:
    tokens = re.findall(r"[A-Za-z0-9]+|\S", expression)
    if not tokens:
        return ""
    prec = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
    output: list[str] = []
    stack: list[str] = []
    expect_operand = True
    for tok in tokens:
        if re.fullmatch(r"[A-Za-z0-9]+", tok):
            if not expect_operand:
                raise ValueError(f"unexpected operand {tok!r}")
            output.append(tok)
            expect_operand = False
        elif tok == "(":
            if not expect_operand:
                raise ValueError("unexpected '('")
            stack.append(tok)
        elif tok == ")":
            if expect_operand:
                raise ValueError("unexpected ')'")
            while stack and stack[-1] != "(":
                output.append(stack.pop())
            if not stack:
                raise ValueError("unbalanced ')'")
            stack.pop()
        elif tok in prec:
            if expect_operand:
                raise ValueError(f"unexpected operator {tok!r}")
            while stack and stack[-1] != "(" and (
                prec[stack[-1]] > prec[tok] or (prec[stack[-1]] == prec[tok] and tok != "^")
            ):
                output.append(stack.pop())
            stack.append(tok)
            expect_operand = True
        else:
            raise ValueError(f"unknown character {tok!r}")
    if expect_operand:
        raise ValueError("expression ends unexpectedly")
    while stack:
        op = stack.pop()
        if op == "(":
            raise ValueError("unbalanced '('")
        output.append(op)
    return " ".join(output)
```

Split the string in half and return the reversed right half followed by the reversed left half; halving keeps recursion depth logarithmic so long strings never hit the recursion limit.
```python
def reverse_string_recursive(s: str) -> str:
    if len(s) <= 1:
        return s
    mid = len(s) // 2
    return reverse_string_recursive(s[mid:]) + reverse_string_recursive(s[:mid])
```

Scan characters and, for each uppercase letter, emit an underscore (except at position 0) followed by its lowercase form; all other characters are copied.
```python
def camel_to_snake_case(name: str) -> str:
    out = []
    for i, ch in enumerate(name):
        if "A" <= ch <= "Z":
            if i > 0:
                out.append("_")
            out.append(ch.lower())
        else:
            out.append(ch)
    return "".join(out)
```

Interval DP on substrings: matching ends add 2 to the inner answer, otherwise drop one end and take the better result.
```python
def longest_palindromic_subsequence_size(text: str) -> int:
    n = len(text)
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if text[i] == text[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1] if n else 0
```

Slide a fixed-size window with a character-count dict, removing characters whose count drops to zero; the dict's size is the distinct count of the current window.
```python
def max_distinct_in_window(text: str, window: int) -> int:
    if window < 1 or window > len(text):
        return 0
    counts = {}
    best = 0
    for i, ch in enumerate(text):
        counts[ch] = counts.get(ch, 0) + 1
        if i >= window:
            old = text[i - window]
            counts[old] -= 1
            if counts[old] == 0:
                del counts[old]
        if i >= window - 1:
            best = max(best, len(counts))
    return best
```

Initialize all four buckets to zero so every key is present, then classify each character with the str predicates in a single pass.
```python
def count_char_categories(s: str) -> dict:
    counts = {"upper": 0, "lower": 0, "digit": 0, "other": 0}
    for ch in s:
        if ch.isupper():
            counts["upper"] += 1
        elif ch.islower():
            counts["lower"] += 1
        elif ch.isdigit():
            counts["digit"] += 1
        else:
            counts["other"] += 1
    return counts
```

Pair each point with its successor via zip and sum the Manhattan distance of every leg.
```python
from typing import List, Tuple


def manhattan_path_length(points: List[Tuple[int, int]]) -> int:
    return sum(
        abs(x2 - x1) + abs(y2 - y1)
        for (x1, y1), (x2, y2) in zip(points, points[1:])
    )
```

Translate each word into a list of positions in the custom alphabet; Python compares lists lexicographically with shorter prefixes first, which is exactly the desired ordering.
```python
from typing import List


def sort_by_alien_alphabet(words: List[str], alphabet: str) -> List[str]:
    rank = {ch: i for i, ch in enumerate(alphabet)}
    return sorted(words, key=lambda w: [rank[ch] for ch in w])
```

The only state is the credit balance; dispatch on the event type, emitting outputs and resetting credit exactly when a sale or refund completes.
```python
def vending_session(events: list[str], price: int) -> list[str]:
    credit = 0
    out = []
    for event in events:
        parts = event.split()
        if parts[0] == "coin":
            credit += int(parts[1])
        elif parts[0] == "select":
            if credit >= price:
                out.append("item")
                if credit > price:
                    out.append(f"change {credit - price}")
                credit = 0
            else:
                out.append(f"need {price - credit}")
        elif parts[0] == "refund" and credit > 0:
            out.append(f"refund {credit}")
            credit = 0
    return out
```

Find the first brace group, recursively expand everything after it, and combine the literal prefix with each option and each expanded tail; a set removes duplicates before sorting.
```python
def expand_brace_alternatives(pattern: str) -> list[str]:
    start = pattern.find('{')
    if start == -1:
        return [pattern]
    end = pattern.find('}', start)
    head = pattern[:start]
    options = pattern[start + 1:end].split(',')
    tails = expand_brace_alternatives(pattern[end + 1:])
    return sorted({head + option + tail for option in options for tail in tails})
```

Map 1 to +1 and 0 to -1; a subarray is balanced exactly when the running balance is the same at both of its ends. Remembering the first index at which each balance occurs gives the longest such span in one pass.
```python
from typing import List


def longest_even_split_binary(bits: List[int]) -> int:
    first_seen = {0: -1}
    balance = 0
    best = 0
    for i, b in enumerate(bits):
        balance += 1 if b == 1 else -1
        if balance in first_seen:
            best = max(best, i - first_seen[balance])
        else:
            first_seen[balance] = i
    return best
```

Represent heading as an index into 'NESW' so turns are +/-1 mod 4, and only commit a forward move after checking bounds and the obstacle set.
```python
def robot_with_obstacles(width: int, height: int, obstacles: set[tuple[int, int]],
                         commands: str) -> tuple[int, int, str]:
    headings = "NESW"
    deltas = {"N": (0, 1), "E": (1, 0), "S": (0, -1), "W": (-1, 0)}
    x = y = 0
    h = 0
    for cmd in commands:
        if cmd == "L":
            h = (h - 1) % 4
        elif cmd == "R":
            h = (h + 1) % 4
        elif cmd == "F":
            dx, dy = deltas[headings[h]]
            nx, ny = x + dx, y + dy
            if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
                x, y = nx, ny
    return (x, y, headings[h])
```

Store only non-blank cells in a dict keyed by integer position so the tape is unbounded in both directions; loop applying rules until the halt state or a missing rule, enforcing the step budget, then render the span between the extreme non-blank cells.
```python
from typing import Optional


def run_turing_machine(rules: dict[tuple[str, str], tuple[str, str, str]], tape: str,
                       start: str, halt: str, max_steps: int) -> Optional[str]:
    cells = {i: ch for i, ch in enumerate(tape) if ch != "_"}
    head = 0
    state = start
    steps = 0
    while state != halt:
        key = (state, cells.get(head, "_"))
        if key not in rules:
            break
        if steps == max_steps:
            return None
        write, move, state = rules[key]
        if write == "_":
            cells.pop(head, None)
        else:
            cells[head] = write
        head += 1 if move == "R" else -1
        steps += 1
    if not cells:
        return ""
    lo, hi = min(cells), max(cells)
    return "".join(cells.get(i, "_") for i in range(lo, hi + 1))
```

Binary search for the left edge of a length-k window: if the element just past the window is strictly closer than the window's first element, the window must shift right; ties keep the smaller left element.
```python
from typing import List


def k_nearest_in_sorted(sorted_nums: List[int], target: int, k: int) -> List[int]:
    n = len(sorted_nums)
    if k <= 0:
        return []
    if k >= n:
        return list(sorted_nums)
    lo, hi = 0, n - k
    while lo < hi:
        mid = (lo + hi) // 2
        if target - sorted_nums[mid] > sorted_nums[mid + k] - target:
            lo = mid + 1
        else:
            hi = mid
    return sorted_nums[lo:lo + k]
```

Exactly-k is not monotone, but at-most-k is: a sliding window counts all subarrays with at most k distinct values ending at each index. Subtracting the at-most-(k-1) count leaves exactly k, all in O(n).
```python
from collections import defaultdict
from typing import List, Hashable


def count_runs_exactly_k_distinct(items: List[Hashable], k: int) -> int:
    def at_most(limit: int) -> int:
        if limit <= 0:
            return 0
        counts = defaultdict(int)
        left = 0
        total = 0
        for right, item in enumerate(items):
            counts[item] += 1
            while len(counts) > limit:
                old = items[left]
                counts[old] -= 1
                if counts[old] == 0:
                    del counts[old]
                left += 1
            total += right - left + 1
        return total

    return at_most(k) - at_most(k - 1)
```

Before the gap every element satisfies nums[i] - nums[0] == i and after it the offset is one larger, so binary search for the first index where that equality breaks; the missing value is base + that index.
```python
from typing import List, Optional


def missing_from_consecutive_run(sorted_nums: List[int]) -> Optional[int]:
    if not sorted_nums:
        return None
    base = sorted_nums[0]
    if sorted_nums[-1] - base == len(sorted_nums) - 1:
        return None
    lo, hi = 0, len(sorted_nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_nums[mid] - base == mid:
            lo = mid + 1
        else:
            hi = mid
    return base + lo
```

Iterate over the smaller dict and look up matching indices in the larger one, so the cost is proportional to the sparser vector.
```python
def sparse_vector_dot(a: dict, b: dict) -> float:
    if len(a) > len(b):
        a, b = b, a
    return sum(value * b[i] for i, value in a.items() if i in b)
```

Characters already forming the longest palindromic subsequence can stay; every other character needs a mirrored partner inserted. The LPS length equals the LCS of the string and its reverse, computed with a rolling-row DP.
```python
def min_insertions_to_palindrome(text: str) -> int:
    n = len(text)
    if n == 0:
        return 0
    rev = text[::-1]
    prev = [0] * (n + 1)
    for i in range(1, n + 1):
        cur = [0] * (n + 1)
        for j in range(1, n + 1):
            if text[i - 1] == rev[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = max(prev[j], cur[j - 1])
        prev = cur
    return n - prev[n]
```

Maintain mappings in both directions; a conflict in either direction means the correspondence is not a bijection, so the patterns differ.
```python
def same_letter_pattern(first: str, second: str) -> bool:
    if len(first) != len(second):
        return False
    forward, backward = {}, {}
    for a, b in zip(first, second):
        if forward.setdefault(a, b) != b or backward.setdefault(b, a) != a:
            return False
    return True
```

Scan p upward from 2 to n / 2 and return the first p where both p and n - p are prime; Goldbach pairs are found very early in practice, so trial-division primality is enough.
```python
from math import isqrt
from typing import Optional


def goldbach_smallest_pair(n: int) -> Optional[tuple[int, int]]:
    if n <= 2 or n % 2:
        return None

    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        return all(x % d for d in range(3, isqrt(x) + 1, 2))

    for p in range(2, n // 2 + 1):
        if is_prime(p) and is_prime(n - p):
            return (p, n - p)
    return None
```

Recursive descent on a shared cursor, dispatching on the type prefix: 'i' reads up to 'e' and validates with a regex, digits read a length then slice exactly that many characters (so the payload may contain ':' or 'e'), and 'l'/'d' loop until their closing 'e'. A final position check rejects trailing data.
```python
import re


def decode_bencode(data: str) -> object:
    pos = 0

    def parse() -> object:
        nonlocal pos
        if pos >= len(data):
            raise ValueError("unexpected end of data")
        ch = data[pos]
        if ch == "i":
            end = data.find("e", pos)
            if end == -1:
                raise ValueError("unterminated integer")
            body = data[pos + 1:end]
            if not re.fullmatch(r"0|-?[1-9][0-9]*", body):
                raise ValueError(f"invalid integer {body!r}")
            pos = end + 1
            return int(body)
        if ch == "l":
            pos += 1
            items = []
            while pos < len(data) and data[pos] != "e":
                items.append(parse())
            if pos >= len(data):
                raise ValueError("unterminated list")
            pos += 1
            return items
        if ch == "d":
            pos += 1
            result = {}
            while pos < len(data) and data[pos] != "e":
                if not "0" <= data[pos] <= "9":
                    raise ValueError("dictionary key must be a string")
                key = parse()
                result[key] = parse()
            if pos >= len(data):
                raise ValueError("unterminated dictionary")
            pos += 1
            return result
        if "0" <= ch <= "9":
            colon = data.find(":", pos)
            if colon == -1:
                raise ValueError("missing ':' after string length")
            length_text = data[pos:colon]
            if not re.fullmatch(r"0|[1-9][0-9]*", length_text):
                raise ValueError(f"invalid string length {length_text!r}")
            start = colon + 1
            end = start + int(length_text)
            if end > len(data):
                raise ValueError("string runs past end of data")
            pos = end
            return data[start:end]
        raise ValueError(f"unexpected character {ch!r} at position {pos}")

    value = parse()
    if pos != len(data):
        raise ValueError("trailing data")
    return value
```

Sort the values and build subsets in increasing index order; each feasible extension is one subset plus all its own extensions, and once the product exceeds the limit every later (larger) value can be pruned.
```python
def count_subsets_product_at_most(nums: list[int], limit: int) -> int:
    values = sorted(nums)

    def extend(start: int, product: int) -> int:
        count = 0
        for i in range(start, len(values)):
            new_product = product * values[i]
            if new_product > limit:
                break
            count += 1 + extend(i + 1, new_product)
        return count

    return extend(0, 1)
```

Map '1' to +1 and '0' to -1; a balanced substring is a span between two equal prefix balances, so store the first index of each balance in a dict and measure the longest gap.
```python
def longest_balanced_binary_span(bits: str) -> int:
    first_index = {0: -1}
    balance = 0
    best = 0
    for i, b in enumerate(bits):
        balance += 1 if b == "1" else -1
        if balance in first_index:
            best = max(best, i - first_index[balance])
        else:
            first_index[balance] = i
    return best
```

The depth of a list is one plus the deepest of its sublists, with zero extra depth when there are no sublists; recursion mirrors that definition directly.
```python
def max_list_nesting_depth(data: list) -> int:
    return 1 + max(
        (max_list_nesting_depth(x) for x in data if isinstance(x, list)),
        default=0,
    )
```

Split on dots and require exactly four parts, then validate each as ASCII digits without a leading zero and within 0-255. Any failure returns None immediately.
```python
def parse_ipv4_address(address: str) -> tuple[int, int, int, int] | None:
    parts = address.split(".")
    if len(parts) != 4:
        return None
    octets = []
    for part in parts:
        if not (part.isascii() and part.isdigit()) or (len(part) > 1 and part[0] == "0"):
            return None
        value = int(part)
        if value > 255:
            return None
        octets.append(value)
    return tuple(octets)
```

Lowercase the text, turn it into a set of characters, and check that the vowel set is a subset of it.
```python
def contains_every_vowel(text: str) -> bool:
    return set("aeiou") <= set(text.lower())
```

Traverse the list, recursing into sublists and counting leaf elements equal to the target; the total is the sum over all levels.
```python
def count_nested_occurrences(data: list, target) -> int:
    count = 0
    for item in data:
        if isinstance(item, list):
            count += count_nested_occurrences(item, target)
        elif item == target:
            count += 1
    return count
```

Accumulate digit characters into a pending count; when a non-digit arrives, emit it repeated count times (default 1) and reset. A leftover count at the end means the input was truncated.
```python
def run_length_decode(encoded: str) -> str:
    out: list[str] = []
    count = ""
    for ch in encoded:
        if "0" <= ch <= "9":
            count += ch
        else:
            out.append(ch * (int(count) if count else 1))
            count = ""
    if count:
        raise ValueError("encoded string ends with a dangling count")
    return "".join(out)
```

Process each line independently: split once on the marker, keep the left part and rstrip it, then rejoin with newlines so the line count is unchanged.
```python
def strip_line_comments(source: str, marker: str = "#") -> str:
    return "\n".join(line.split(marker, 1)[0].rstrip() for line in source.split("\n"))
```

Generate combinations in non-increasing coin order by only allowing coins at or after the current coin's index, which avoids permutations of the same multiset; then sort the tuples.
```python
def coin_partitions_listing(amount: int, coins: list[int]) -> list[tuple[int, ...]]:
    values = sorted(set(coins), reverse=True)
    result = []
    current = []

    def backtrack(remaining: int, first: int) -> None:
        if remaining == 0:
            result.append(tuple(current))
            return
        for i in range(first, len(values)):
            coin = values[i]
            if coin <= remaining:
                current.append(coin)
                backtrack(remaining - coin, i)
                current.pop()

    backtrack(amount, 0)
    return sorted(result)
```

Andrew's monotone chain: sort points, build lower and upper chains with a stack that pops on non-left turns (which also drops collinear points), then concatenate the chains without their duplicated endpoints.
```python
from typing import List, Tuple


def convex_hull_ccw(points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    pts = sorted(set(points))
    if len(pts) <= 1:
        return pts

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]
```

Split states by whether the last two posts match: a matching pair can only follow a differing pair, and a differing post can follow either state in colors-1 ways.
```python
def fence_colorings_no_triple(posts: int, colors: int) -> int:
    if posts <= 0 or colors <= 0:
        return 0
    same, diff = 0, colors  # last two equal / last two different
    for _ in range(posts - 1):
        same, diff = diff, (same + diff) * (colors - 1)
    return same + diff
```

Run a multi-source BFS seeded with every zero cell at distance 0; each cell is first reached via its nearest zero, so one O(R*C) pass fills the answer.
```python
from collections import deque
from typing import List


def distance_to_nearest_zero(grid: List[List[int]]) -> List[List[int]]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    dist = [[-1] * cols for _ in range(rows)]
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                dist[r][c] = 0
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                queue.append((nr, nc))
    return dist
```

Track how many valid strings end in 0 versus 1: a 0 can follow anything, a 1 only a 0. The final count is the total of both states after n characters.
