Handle each comma-separated item by first splitting off an optional step, then resolving the base to a (start, end) pair: '*' gives the full range, 'A-B' an explicit one, and 'N' a single value or N..high when stepped. range(start, end + 1, step) does the expansion, and a set merges the items.
```python
def expand_cron_field(field: str, low: int, high: int) -> list[int]:
    def number(text: str) -> int:
        if not (text.isascii() and text.isdigit()):
            raise ValueError(f"invalid number {text!r}")
        value = int(text)
        if not low <= value <= high:
            raise ValueError(f"value {value} out of range {low}-{high}")
        return value

    selected: set[int] = set()
    for item in field.split(","):
        base, slash, step_text = item.partition("/")
        if slash:
            if not (step_text.isascii() and step_text.isdigit()) or int(step_text) == 0:
                raise ValueError(f"invalid step {step_text!r}")
            step = int(step_text)
        else:
            step = 1
        if base == "*":
            start, end = low, high
        elif "-" in base:
            a, _, b = base.partition("-")
            start, end = number(a), number(b)
            if start > end:
                raise ValueError(f"descending range {base!r}")
        else:
            start = number(base)
            end = high if slash else start
        selected.update(range(start, end + 1, step))
    return sorted(selected)
```

Tokenize with a regex, then use recursive descent with one function per precedence level: expr (+,-) over term (*,/) over factor (unary signs) over power. Making the exponent's right operand a factor gives right associativity and lets '^' bind tighter than a leading minus.
```python
import re


def evaluate_arithmetic_expression(expression: str) -> float:
    tokens = re.findall(r"\s*([0-9]+(?:\.[0-9]+)?|[-+*/^()]|\S)", expression)
    pos = 0

    def peek() -> str | None:
        return tokens[pos] if pos < len(tokens) else None

    def take() -> str:
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        pos += 1
        return tok

    def parse_expr() -> float:
        value = parse_term()
        while peek() in ("+", "-"):
            op = take()
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term() -> float:
        value = parse_factor()
        while peek() in ("*", "/"):
            op = take()
            rhs = parse_factor()
            value = value * rhs if op == "*" else value / rhs
        return value

    def parse_factor() -> float:
        if peek() in ("+", "-"):
            op = take()
            operand = parse_factor()
            return operand if op == "+" else -operand
        return parse_power()

    def parse_power() -> float:
        base = parse_atom()
        if peek() == "^":
            take()
            result = base ** parse_factor()
            if isinstance(result, complex):
                raise ValueError("result is not a real number")
            return result
        return base

    def parse_atom() -> float:
        tok = take()
        if tok == "(":
            value = parse_expr()
            if take() != ")":
                raise ValueError("expected ')'")
            return value
        if tok[0] in "0123456789":
            return float(tok)
        raise ValueError(f"unexpected token {tok!r}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return float(result)
```

