State DP over transactions used: holding[t] is the best balance while holding the t-th share, free[t] after completing t trades; when k is large the limit is irrelevant and we sum all upward moves.
```python
from typing import List


def max_gain_with_trade_limit(prices: List[int], max_trades: int) -> int:
    if not prices or max_trades <= 0:
        return 0
    if max_trades >= len(prices) // 2:
        return sum(max(0, b - a) for a, b in zip(prices, prices[1:]))
    holding = [float("-inf")] * (max_trades + 1)
    free = [0] * (max_trades + 1)
    for p in prices:
        for t in range(1, max_trades + 1):
            holding[t] = max(holding[t], free[t - 1] - p)
            free[t] = max(free[t], holding[t] + p)
    return free[max_trades]
```

Choose the first palindromic piece starting at the current index and recurse on the remainder, summing the counts; memoizing on the start index avoids recomputing shared suffixes.
```python
from functools import lru_cache


def count_palindromic_partitions(s: str) -> int:
    n = len(s)

    @lru_cache(maxsize=None)
    def ways(start: int) -> int:
        if start == n:
            return 1
        total = 0
        for end in range(start + 1, n + 1):
            piece = s[start:end]
            if piece == piece[::-1]:
                total += ways(end)
        return total

    return ways(0)
```

Since the grid is finite the dynamics are eventually periodic; hash each generation (as a tuple of row strings) into a dict mapping state to the generation it first appeared, and the first repeat gives both the cycle start and the period.
```python
from typing import Optional


def life_cycle_detection(grid: list[str], max_generations: int) -> Optional[tuple[int, int]]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def step(state: tuple[str, ...]) -> tuple[str, ...]:
        out = []
        for r in range(rows):
            row = []
            for c in range(cols):
                n = sum(
                    state[rr][cc] == "#"
                    for rr in range(max(0, r - 1), min(rows, r + 2))
                    for cc in range(max(0, c - 1), min(cols, c + 2))
                    if (rr, cc) != (r, c)
                )
                row.append("#" if n == 3 or (n == 2 and state[r][c] == "#") else ".")
            out.append("".join(row))
        return tuple(out)

    state = tuple(grid)
    seen = {state: 0}
    for gen in range(1, max_generations + 1):
        state = step(state)
        if state in seen:
            return (seen[state], gen - seen[state])
        seen[state] = gen
    return None
```

Equivalent to subset-sum for half the total: a 1-D boolean table updated right-to-left so each item is used at most once.
```python
from typing import List


def splits_into_equal_sum_groups(weights: List[int]) -> bool:
    total = sum(weights)
    if total % 2:
        return False
    half = total // 2
    reachable = [True] + [False] * half
    for w in weights:
        for s in range(half, w - 1, -1):
            if reachable[s - w]:
                reachable[s] = True
    return reachable[half]
```

Compress the x-coordinates into vertical slabs; within each slab the active rectangles are exactly those spanning it, so the covered height is a 1-D interval union, and summing height times slab width gives the area.
```python
from typing import List, Tuple


def union_area_of_rectangles(rects: List[Tuple[int, int, int, int]]) -> int:
    rects = [r for r in rects if r[0] < r[2] and r[1] < r[3]]
    if not rects:
        return 0
    xs = sorted({x for r in rects for x in (r[0], r[2])})
    total = 0
    for left, right in zip(xs, xs[1:]):
        spans = sorted((y1, y2) for x1, y1, x2, y2 in rects if x1 <= left and right <= x2)
        covered = 0
        cur_lo = cur_hi = None
        for lo, hi in spans:
            if cur_hi is None or lo > cur_hi:
                if cur_hi is not None:
                    covered += cur_hi - cur_lo
                cur_lo, cur_hi = lo, hi
            else:
                cur_hi = max(cur_hi, hi)
        if cur_hi is not None:
            covered += cur_hi - cur_lo
        total += covered * (right - left)
    return total
```

Binary search on the sum value: for a candidate limit, count pairs with sum <= limit in linear time using a pointer into b that only moves left as a increases. The smallest limit with count >= k is the answer.
```python
from typing import List


def kth_smallest_cross_sum(a: List[int], b: List[int], k: int) -> int:
    def count_at_most(limit: int) -> int:
        count, j = 0, len(b) - 1
        for x in a:
            while j >= 0 and x + b[j] > limit:
                j -= 1
            count += j + 1
        return count

    lo, hi = a[0] + b[0], a[-1] + b[-1]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
```

This is the canonical predicate binary search: keep the invariant that everything before lo is False and everything from hi on is True, then map the "not found" position len(flags) to -1.
