from typing import List


def has_pair_with_gap(nums: List[int], gap: int) -> bool:
    values = sorted(nums)
    i, j = 0, 1
    while j < len(values):
        if i == j:
            j += 1
            continue
        diff = values[j] - values[i]
        if diff == gap:
            return True
        if diff < gap:
            j += 1
        else:
            i += 1
    return False
