Process line by line with a 'current section' variable. Headers create the section dict via setdefault (so empty sections still appear), and key lines create the implicit '' section lazily only when a key lands there.
```python
def parse_ini_text(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    current = ""
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line[0] in ";#":
            continue
        if line.startswith("[") and line.endswith("]"):
            current = line[1:-1].strip()
            sections.setdefault(current, {})
        elif "=" in line:
            key, _, value = line.partition("=")
            sections.setdefault(current, {})[key.strip()] = value.strip()
        else:
            raise ValueError(f"line {lineno}: cannot parse {raw!r}")
