Each cell's best sum is its value plus the better of the best sums above and to the left; the first row and column have only one predecessor.
```python
from typing import List


def richest_right_down_path(grid: List[List[int]]) -> int:
    cols = len(grid[0])
    best = [0] * cols
    for r, row in enumerate(grid):
        for c in range(cols):
            if r == 0 and c == 0:
                best[c] = row[c]
            elif r == 0:
                best[c] = best[c - 1] + row[c]
            elif c == 0:
                best[c] = best[c] + row[c]
            else:
                best[c] = max(best[c], best[c - 1]) + row[c]
    return best[-1]
