Build the next grid from the old one (never in place), counting the eight in-bounds neighbours of each cell and applying the survive-on-2-or-3, birth-on-3 rule.
```python
def life_next_generation(grid: list[str]) -> list[str]:
    rows = len(grid)
    result = []
    for r in range(rows):
        cols = len(grid[r])
        new_row = []
        for c in range(cols):
            alive = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < rows and 0 <= cc < len(grid[rr]) and grid[rr][cc] == "#":
                        alive += 1
            if alive == 3 or (alive == 2 and grid[r][c] == "#"):
                new_row.append("#")
            else:
                new_row.append(".")
        result.append("".join(new_row))
    return result
```

