```python
def region_sizes_descending(grid: list[str]) -> list[int]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    seen = set()

    def fill(r: int, c: int) -> int:
        if not (0 <= r < rows and 0 <= c < cols):
            return 0
        if grid[r][c] != '#' or (r, c) in seen:
            return 0
        seen.add((r, c))
        return 1 + fill(r + 1, c) + fill(r - 1, c) + fill(r, c + 1) + fill(r, c - 1)

    sizes = [fill(r, c) for r in range(rows) for c in range(cols)
             if grid[r][c] == '#' and (r, c) not in seen]
    return sorted(sizes, reverse=True)
```

Binary search over candidate roots for the last r satisfying r*r <= n; the upper-mid choice (lo+hi+1)//2 guarantees progress when moving lo up.
```python
def integer_sqrt_floor(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    lo, hi = 0, n // 2 + 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo
```

Because sandpile toppling is order-independent (abelian), a worklist of unstable cells suffices; each pop topples a cell divmod(v, 4) times at once and pushes neighbours that become unstable.
```python
def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    g = [row[:] for row in grid]
    rows = len(g)
    stack = [(r, c) for r in range(rows) for c in range(len(g[r])) if g[r][c] >= 4]
    while stack:
        r, c = stack.pop()
        if g[r][c] < 4:
            continue
        q, g[r][c] = divmod(g[r][c], 4)
        for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= rr < rows and 0 <= cc < len(g[rr]):
                g[rr][cc] += q
                if g[rr][cc] >= 4:
                    stack.append((rr, cc))
    return g
```

Count decodings of each prefix: the last digit alone contributes the previous prefix's count if it is non-zero, and the last two digits contribute the count two back if they form 10..26.
```python
def count_letter_code_decodings(code: str) -> int:
    prev2, prev1 = 1, 1  # ways for prefixes of length i-2 and i-1
    for i in range(1, len(code) + 1):
        cur = 0
        if code[i - 1] != "0":
            cur += prev1
        if i >= 2 and code[i - 2] != "0" and 10 <= int(code[i - 2:i]) <= 26:
            cur += prev2
        prev2, prev1 = prev1, cur
    return prev1
```

Sort intervals by start and advance a cursor marking how far [lo, hi] is covered; any interval starting beyond the cursor exposes a gap, and whatever remains after the sweep is the final gap.
```python
from typing import List, Tuple


def uncovered_gaps(intervals: List[Tuple[int, int]], lo: int, hi: int) -> List[Tuple[int, int]]:
    gaps = []
    cursor = lo
    for start, end in sorted(intervals):
        if end <= cursor:
            continue
        if start > cursor:
            gaps.append((cursor, min(start, hi)))
        cursor = max(cursor, end)
        if cursor >= hi:
            break
    if cursor < hi:
        gaps.append((cursor, hi))
    return [(a, b) for a, b in gaps if a < b]
```

