0/1 knapsack with a 1-D table indexed by capacity, iterating capacities downward so each item is considered once.
```python
from typing import List


def best_backpack_value(weights: List[int], values: List[int], capacity: int) -> int:
    best = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        for c in range(capacity, w - 1, -1):
            best[c] = max(best[c], best[c - w] + v)
    return best[capacity]
```

A bijection needs two dicts, one in each direction; setdefault records the first pairing and any later mismatch in either direction breaks the pattern.
```python
def follows_word_pattern(pattern: str, sentence: str) -> bool:
    words = sentence.split()
    if len(words) != len(pattern):
        return False
    char_to_word = {}
    word_to_char = {}
    for ch, word in zip(pattern, words):
        if char_to_word.setdefault(ch, word) != word:
            return False
        if word_to_char.setdefault(word, ch) != ch:
            return False
    return True
```

span[i] is the longest balanced substring ending at i: a ')' either closes an adjacent '(' or the '(' just before the balanced block ending at i-1, and we then glue on the balanced block preceding that opener.
```python
def longest_balanced_paren_span(text: str) -> int:
    n = len(text)
    span = [0] * n  # longest balanced substring ending at index i
    best = 0
    for i in range(1, n):
        if text[i] != ")":
            continue
        if text[i - 1] == "(":
            span[i] = 2 + (span[i - 2] if i >= 2 else 0)
        else:
            j = i - span[i - 1] - 1
            if j >= 0 and text[j] == "(":
                span[i] = span[i - 1] + 2 + (span[j - 1] if j >= 1 else 0)
        best = max(best, span[i])
    return best
```

ways[i] counts segmentations of the first i characters; add ways[i - len(w)] for each dictionary word that ends exactly at i.
```python
from typing import List


def count_dictionary_segmentations(text: str, words: List[str]) -> int:
    vocab = {w for w in words if w}
    lengths = sorted({len(w) for w in vocab})
    ways = [1] + [0] * len(text)
    for end in range(1, len(text) + 1):
        for size in lengths:
            if size > end:
                break
            if text[end - size:end] in vocab:
                ways[end] += ways[end - size]
    return ways[len(text)]
```

Enumerate divisors in pairs (d, n // d) up to sqrt(n), starting the total at 1 and taking care not to double count a square root.
