```

Backtrack from every start vertex, extending the path to unvisited neighbours and counting completions; caching on (current vertex, visited bitmask) turns the factorial search into O(2^n * n^2).
```python
from functools import lru_cache


def count_hamiltonian_paths(n: int, edges: list[tuple[int, int]]) -> int:
    if n == 0:
        return 0
    neighbors = [set() for _ in range(n)]
    for u, v in edges:
        if u != v:
            neighbors[u].add(v)
            neighbors[v].add(u)
    full = (1 << n) - 1

    @lru_cache(maxsize=None)
    def paths_from(last: int, visited: int) -> int:
        if visited == full:
            return 1
        return sum(
            paths_from(v, visited | (1 << v))
            for v in neighbors[last]
            if not visited & (1 << v)
        )

    return sum(paths_from(start, 1 << start) for start in range(n))
```

Split on commas, partition range items on the first '-', and validate both ends with a small helper (a second '-' makes the right side invalid). A set collects values and sorting gives the final list.
```python
def expand_number_ranges(spec: str) -> list[int]:
    def to_int(s: str) -> int:
        s = s.strip()
        if not (s.isascii() and s.isdigit()):
            raise ValueError(f"invalid number: {s!r}")
        return int(s)

    values: set[int] = set()
    for item in spec.split(","):
        if not item.strip():
            continue
        if "-" in item:
            lo_text, _, hi_text = item.partition("-")
            lo, hi = to_int(lo_text), to_int(hi_text)
            if lo > hi:
                raise ValueError(f"descending range: {item.strip()!r}")
            values.update(range(lo, hi + 1))
        else:
            values.add(to_int(item))
    return sorted(values)
```

Run Dijkstra over states (cell, incoming direction) because the cost of the next step depends on the direction just taken; edge weights are 1 plus the turn penalty when the direction changes.
```python
import heapq
from typing import List


def min_cost_path_with_turn_penalty(grid: List[str], turn_cost: int) -> int:
    if not grid or not grid[0]:
        return -1
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[rows - 1][cols - 1] == '#':
        return -1
    if rows == 1 and cols == 1:
        return 0
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))
    dist = {}
    heap = []
    for d, (dr, dc) in enumerate(directions):
        nr, nc = dr, dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
            dist[(nr, nc, d)] = 1
            heapq.heappush(heap, (1, nr, nc, d))
    while heap:
        cost, r, c, d = heapq.heappop(heap)
        if cost > dist.get((r, c, d), float('inf')):
            continue
        if (r, c) == (rows - 1, cols - 1):
            return cost
        for nd, (dr, dc) in enumerate(directions):
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                continue
            ncost = cost + 1 + (turn_cost if nd != d else 0)
            if ncost < dist.get((nr, nc, nd), float('inf')):
                dist[(nr, nc, nd)] = ncost
                heapq.heappush(heap, (ncost, nr, nc, nd))
    return -1
```

The cost sum of ceil(x/d) is non-increasing in d, and d = max(nums) always meets a budget of at least len(nums), so binary search on d in [1, max(nums)] for the first feasible divisor.
```python
from typing import List


def smallest_divisor_within_budget(nums: List[int], budget: int) -> int:
    if not nums:
        return 1

    def cost(d: int) -> int:
        return sum((x + d - 1) // d for x in nums)

    lo, hi = 1, max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if cost(mid) <= budget:
            hi = mid
        else:
            lo = mid + 1
    return lo
```

Flood fill from the seed with an explicit stack and a visited set, expanding only into neighbors with the seed's value; the visited set's size is the region size.
```python
from typing import List


def connected_region_size(grid: List[List[int]], r: int, c: int) -> int:
    rows = len(grid)
    if not (0 <= r < rows and 0 <= c < len(grid[r])):
        return 0
    target = grid[r][c]
    seen = {(r, c)}
    stack = [(r, c)]
    while stack:
        cr, cc = stack.pop()
        for nr, nc in ((cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)):
            if (0 <= nr < rows and 0 <= nc < len(grid[nr])
                    and (nr, nc) not in seen and grid[nr][nc] == target):
                seen.add((nr, nc))
                stack.append((nr, nc))
    return len(seen)
```

