Backtrack by choosing the next piece of length 1 to 3, stopping early on a leading zero or a value above 255, and count the ways that consume the whole string with exactly the requested number of pieces.
```python
def count_byte_value_splits(digits: str, parts: int) -> int:
    n = len(digits)

    def count(i: int, remaining: int) -> int:
        if remaining == 0:
            return 1 if i == n else 0
        total = 0
        for length in range(1, 4):
            if i + length > n:
                break
            piece = digits[i:i + length]
            if length > 1 and piece[0] == '0':
                break
            if int(piece) > 255:
                break
            total += count(i + length, remaining - 1)
        return total

    return count(0, parts)
