Sort, then sweep two pointers inward: a sum below the target can only get closer by raising the left value, and one above by lowering the right value. Track the best sum with an explicit tie-break toward the smaller sum.
```python
from typing import List


def pair_sum_nearest_target(nums: List[int], target: int) -> int:
    values = sorted(nums)
    lo, hi = 0, len(values) - 1
    best = values[lo] + values[hi]
    while lo < hi:
        s = values[lo] + values[hi]
        if abs(s - target) < abs(best - target) or (
            abs(s - target) == abs(best - target) and s < best
        ):
            best = s
        if s < target:
            lo += 1
        elif s > target:
            hi -= 1
        else:
            return s
    return best
```

Run a small state machine over the characters with a word buffer plus an explicit in_word flag, which is what lets '' produce an empty word. Each quoting mode has its own inner scan with its own escape rules, and words are flushed only on unquoted whitespace and at the end.
```python
def split_shell_words(command: str) -> list[str]:
    words: list[str] = []
    current: list[str] = []
    in_word = False
    i, n = 0, len(command)
    while i < n:
        ch = command[i]
        if ch.isspace():
            if in_word:
                words.append("".join(current))
                current, in_word = [], False
            i += 1
        elif ch == "'":
            end = command.find("'", i + 1)
            if end == -1:
                raise ValueError("unterminated single quote")
            current.append(command[i + 1:end])
            in_word = True
            i = end + 1
        elif ch == '"':
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                c = command[i]
                if c == '"':
                    i += 1
                    break
                if c == "\\" and i + 1 < n and command[i + 1] in '"\\':
                    current.append(command[i + 1])
                    i += 2
                else:
                    current.append(c)
                    i += 1
            in_word = True
        elif ch == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            current.append(command[i + 1])
            in_word = True
            i += 2
        else:
            current.append(ch)
            in_word = True
            i += 1
    if in_word:
        words.append("".join(current))
    return words
```

The last move into the target is either from above or from the left, so paths(r, c) = paths(r-1, c) + paths(r, c-1), with a single row or column having exactly one path; memoization makes it polynomial.
