Tokenize with a regex, then build the tree iteratively with an explicit stack of open lists, so there is no recursion limit: '(' pushes a new list, ')' pops it into its parent or marks the top-level result as finished. Any token after completion, or lists still open at the end, is an error.
```python
import re


def parse_s_expression(text: str) -> object:
    tokens = re.findall(r"[()]|[^\s()]+", text)
    if not tokens:
        raise ValueError("empty input")

    def atom(tok: str) -> object:
        return int(tok) if re.fullmatch(r"[+-]?[0-9]+", tok) else tok

    stack: list[list] = []
    result: object = None
    done = False
    for tok in tokens:
        if done:
            raise ValueError(f"unexpected token after expression: {tok!r}")
        if tok == "(":
            stack.append([])
        elif tok == ")":
            if not stack:
                raise ValueError("unexpected ')'")
            finished = stack.pop()
            if stack:
                stack[-1].append(finished)
            else:
                result, done = finished, True
        elif stack:
            stack[-1].append(atom(tok))
        else:
            result, done = atom(tok), True
    if stack:
        raise ValueError("unbalanced '('")
    return result
```

