Kahn's topological sort with a min-heap of ready nodes yields the lexicographically smallest order; if some nodes never reach in-degree zero there is a cycle.
```python
import heapq


def dependency_install_order(deps: dict) -> list:
    nodes = set(deps)
    for reqs in deps.values():
        nodes.update(reqs)
    indegree = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for pkg, reqs in deps.items():
        for req in set(reqs):
            dependents[req].append(pkg)
            indegree[pkg] += 1
    ready = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        n = heapq.heappop(ready)
        order.append(n)
        for m in dependents[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(ready, m)
    if len(order) != len(nodes):
        raise ValueError("dependency cycle")
    return order
```

