Recursively choose a dictionary word that prefixes the remaining text and combine it with every segmentation of the suffix; memoizing segmentations per start index keeps dead-end suffixes from being re-explored exponentially.
```python
from functools import lru_cache


def all_word_break_sentences(s: str, words: list[str]) -> list[str]:
    vocabulary = set(words)
    lengths = sorted({len(w) for w in vocabulary if w})

    @lru_cache(maxsize=None)
    def segment(start: int) -> tuple[tuple[str, ...], ...]:
        if start == len(s):
            return ((),)
        results = []
        for length in lengths:
            word = s[start:start + length]
            if len(word) < length:
                break
            if word in vocabulary:
                for rest in segment(start + length):
                    results.append((word,) + rest)
        return tuple(results)

    return sorted(' '.join(parts) for parts in segment(0))
```

