from typing import List


def fewest_hops_to_last_index(reach: List[int]) -> int:
    n = len(reach)
    if n == 0:
        return -1
    hops, frontier_end, farthest = 0, 0, 0
    for i in range(n - 1):
        farthest = max(farthest, i + reach[i])
        if i == frontier_end:
            if farthest <= i:
                return -1
            hops += 1
            frontier_end = farthest
            if frontier_end >= n - 1:
                break
    return hops
