Check divisibility, then place numbers largest-first into k buckets by backtracking, never exceeding the target sum and skipping buckets whose current sum was already tried at this level since they are interchangeable.
```python
def can_split_into_equal_sum_groups(nums: list[int], k: int) -> bool:
    if len(nums) < k or not nums:
        return False
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    values = sorted(nums, reverse=True)
    if values[0] > target:
        return False
    sums = [0] * k

    def place(i: int) -> bool:
        if i == len(values):
            return True
        tried = set()
        for g in range(k):
            if sums[g] in tried or sums[g] + values[i] > target:
                continue
            tried.add(sums[g])
            sums[g] += values[i]
            if place(i + 1):
                return True
            sums[g] -= values[i]
        return False

    return place(0)
```

Use a sliding window that grows on the right and shrinks from the left whenever it holds more than k distinct characters; record a new best only on a strictly longer window so the earliest one wins ties.
```python
def longest_k_distinct_substring(text: str, k: int) -> str:
    if k <= 0:
        return ""
    counts = {}
    left = 0
    best_start, best_len = 0, 0
    for right, ch in enumerate(text):
        counts[ch] = counts.get(ch, 0) + 1
        while len(counts) > k:
            old = text[left]
            counts[old] -= 1
            if counts[old] == 0:
                del counts[old]
            left += 1
        if right - left + 1 > best_len:
            best_start, best_len = left, right - left + 1
    return text[best_start:best_start + best_len]
```

