A subarray sum is a difference of two prefix sums, so count pairs i < j with prefix[j] - prefix[i] in range. Merge sort over the prefix array does this in O(n log n): with both halves sorted, two monotone pointers find, for each left prefix, the block of right prefixes in range.
```python
from typing import List


def count_runs_sum_in_range(nums: List[int], lower: int, upper: int) -> int:
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)

    def sort_count(lo: int, hi: int) -> int:
        if hi - lo <= 1:
            return 0
        mid = (lo + hi) // 2
        count = sort_count(lo, mid) + sort_count(mid, hi)
        a = b = mid
        for i in range(lo, mid):
            while a < hi and prefix[a] - prefix[i] < lower:
                a += 1
            while b < hi and prefix[b] - prefix[i] <= upper:
                b += 1
            count += b - a
        prefix[lo:hi] = sorted(prefix[lo:hi])
        return count

    return sort_count(0, len(prefix))
```

