Interval DP over chains i..j: try every split point k, paying the two sub-chain costs plus the final multiplication dims[i]*dims[k+1]*dims[j+1].
```python
from typing import List


def cheapest_matrix_chain_order(dims: List[int]) -> int:
    count = len(dims) - 1
    if count < 2:
        return 0
    cost = [[0] * count for _ in range(count)]
    for length in range(2, count + 1):
        for i in range(count - length + 1):
            j = i + length - 1
            cost[i][j] = min(
                cost[i][k] + cost[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1]
                for k in range(i, j)
            )
    return cost[0][count - 1]
