A fetch-decode-execute loop over a program counter, resolving operands as literals or register lookups; a step budget checked before each fetch turns non-termination into None while a dict tracks written registers in first-write order.
```python
from typing import Optional


def run_register_machine(program: list[str], max_steps: int) -> Optional[dict[str, int]]:
    regs: dict[str, int] = {}

    def value(token: str) -> int:
        if token.isalpha():
            return regs.get(token, 0)
        return int(token)

    pc = 0
    steps = 0
    while 0 <= pc < len(program):
        if steps == max_steps:
            return None
        op, x, y = program[pc].split()
        steps += 1
        if op == "jnz":
            if value(x) != 0:
                pc += value(y)
                continue
        elif op == "set":
            regs[x] = value(y)
        elif op == "add":
            regs[x] = regs.get(x, 0) + value(y)
        elif op == "mul":
            regs[x] = regs.get(x, 0) * value(y)
        pc += 1
    return regs
```

