Maintain the current window as a sorted list: on each slide, binary-search and remove the outgoing value and insort the incoming one, then read the median from the middle. This is O(n*k) worst case from list shifting but simple and fast in practice; two heaps with lazy deletion would give O(n log k).
```python
import bisect
from typing import List


def rolling_window_medians(nums: List[int], k: int) -> List[float]:
    if k < 1 or k > len(nums):
        return []
    window = sorted(nums[:k])
    result: List[float] = []

    def median() -> float:
        if k % 2:
            return float(window[k // 2])
        return (window[k // 2 - 1] + window[k // 2]) / 2

    result.append(median())
    for i in range(k, len(nums)):
        window.pop(bisect.bisect_left(window, nums[i - k]))
        bisect.insort(window, nums[i])
        result.append(median())
    return result
```

