Scan field by field with an index: a quoted field is consumed character by character, turning doubled quotes into one, while an unquoted field extends to the next comma. After each field we must be at a comma (continue) or end of line (done), which also handles a trailing empty field.
```python
def parse_csv_line(line: str) -> list[str]:
    fields: list[str] = []
    i, n = 0, len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1
            buf: list[str] = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                buf.append(ch)
                i += 1
            if i < n and line[i] != ",":
                raise ValueError(f"unexpected character after closing quote at {i}")
            fields.append("".join(buf))
        else:
            j = line.find(",", i)
            if j == -1:
                j = n
            fields.append(line[i:j])
            i = j
        if i >= n:
            return fields
        i += 1  # skip the comma
```

