Use two indices moving inward: skip non-alphanumeric characters on either side, compare the case-folded characters, and recurse on the inner range until the indices cross.
```python
def is_alnum_palindrome_recursive(s: str) -> bool:
    def check(i: int, j: int) -> bool:
        if i >= j:
            return True
        if not s[i].isalnum():
            return check(i + 1, j)
        if not s[j].isalnum():
            return check(i, j - 1)
        if s[i].lower() != s[j].lower():
            return False
        return check(i + 1, j - 1)

    return check(0, len(s) - 1)
```

