Parse each instruction and dispatch on its opcode against a Python list used as the stack, guarding each operation on the required stack depth.
```python
def run_stack_machine(ops: list[str]) -> list[int]:
    stack: list[int] = []
    for op in ops:
        parts = op.split()
        name = parts[0]
        if name == "push":
            stack.append(int(parts[1]))
        elif name == "pop":
            if stack:
                stack.pop()
        elif name == "add":
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
        elif name == "dup":
            if stack:
                stack.append(stack[-1])
    return stack
```

