Longest simple path is NP-hard, so backtrack: from each start vertex do a DFS that marks vertices on the current path, returns the heaviest extension, and unmarks on the way back.
```python
def max_weight_simple_path(n: int, edges: list[tuple[int, int, int]]) -> int:
    adjacency = [[] for _ in range(n)]
    for u, v, w in edges:
        adjacency[u].append((v, w))
        adjacency[v].append((u, w))
    visited = [False] * n

    def extend(u: int) -> int:
        visited[u] = True
        best = 0
        for v, w in adjacency[u]:
            if not visited[v]:
                best = max(best, w + extend(v))
        visited[u] = False
        return best

    return max((extend(start) for start in range(n)), default=0)
```

First prune to states reachable from 0, then apply Moore's partition refinement: start from accepting vs. non-accepting and repeatedly split blocks by the tuple of successor blocks until the number of blocks stops growing.
```python
def minimal_dfa_state_count(num_states: int, alphabet: str,
                            delta: dict[tuple[int, str], int],
                            accepting: set[int]) -> int:
    reachable = {0}
    frontier = [0]
    while frontier:
        s = frontier.pop()
        for ch in alphabet:
            t = delta[(s, ch)]
            if t not in reachable:
                reachable.add(t)
                frontier.append(t)

    block = {s: int(s in accepting) for s in reachable}
    count = len(set(block.values()))
    while True:
        signatures: dict[tuple, int] = {}
        new_block = {}
        for s in sorted(reachable):
            sig = (block[s],) + tuple(block[delta[(s, ch)]] for ch in alphabet)
            new_block[s] = signatures.setdefault(sig, len(signatures))
        if len(signatures) == count:
            return count
        block, count = new_block, len(signatures)
```

dp over (pattern prefix, text prefix): a literal or '?' advances both diagonally, while '*' either matches nothing (from the row above) or absorbs one more character (from the left).
```python
def glob_pattern_matches(text: str, pattern: str) -> bool:
    n = len(text)
    prev = [True] + [False] * n
    for p in pattern:
        cur = [False] * (n + 1)
        if p == "*":
            cur[0] = prev[0]
            for j in range(1, n + 1):
                cur[j] = prev[j] or cur[j - 1]
        else:
            for j in range(1, n + 1):
                cur[j] = prev[j - 1] and (p == "?" or p == text[j - 1])
        prev = cur
    return prev[n]
```

A hand-written recursive-descent parser over a shared index: dispatch on the first character to object, array, string, literal or number parsers. Numbers use an anchored regex that enforces the no-leading-zero rule, and after the top-level value only whitespace may remain.
```python
import re


def parse_mini_json(text: str) -> object:
    whitespace = " \t\n\r"
    escapes = {'"': '"', "\\": "\\", "/": "/", "n": "\n", "t": "\t", "r": "\r", "b": "\b", "f": "\f"}
    number_re = re.compile(r"-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?")
    n = len(text)
    i = 0

    def skip_ws() -> None:
        nonlocal i
        while i < n and text[i] in whitespace:
            i += 1

    def expect(ch: str) -> None:
        nonlocal i
        if i >= n or text[i] != ch:
            raise ValueError(f"expected {ch!r} at position {i}")
        i += 1

    def parse_value() -> object:
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("unexpected end of input")
        ch = text[i]
        if ch == "{":
            return parse_object()
        if ch == "[":
            return parse_array()
        if ch == '"':
            return parse_string()
        for word, value in (("true", True), ("false", False), ("null", None)):
            if text.startswith(word, i):
                i += len(word)
                return value
        m = number_re.match(text, i)
        if m:
            i = m.end()
            if m.group(1) or m.group(2):
                return float(m.group(0))
            return int(m.group(0))
        raise ValueError(f"unexpected character {ch!r} at position {i}")

    def parse_string() -> str:
        nonlocal i
        expect('"')
        out: list[str] = []
        while True:
            if i >= n:
                raise ValueError("unterminated string")
            ch = text[i]
            i += 1
            if ch == '"':
                return "".join(out)
            if ch == "\\":
                if i >= n:
                    raise ValueError("unterminated escape")
                esc = text[i]
                i += 1
                if esc in escapes:
                    out.append(escapes[esc])
                elif esc == "u":
                    digits = text[i:i + 4]
                    if len(digits) != 4 or any(c not in "0123456789abcdefABCDEF" for c in digits):
                        raise ValueError("invalid unicode escape")
                    out.append(chr(int(digits, 16)))
                    i += 4
                else:
                    raise ValueError(f"invalid escape {esc!r}")
            elif ch < " ":
                raise ValueError("control character in string")
            else:
                out.append(ch)

    def parse_array() -> list:
        nonlocal i
        expect("[")
        items: list = []
        skip_ws()
        if i < n and text[i] == "]":
            i += 1
            return items
        while True:
            items.append(parse_value())
            skip_ws()
            if i < n and text[i] == ",":
                i += 1
                continue
            expect("]")
            return items

    def parse_object() -> dict:
        nonlocal i
        expect("{")
        obj: dict = {}
        skip_ws()
        if i < n and text[i] == "}":
            i += 1
            return obj
        while True:
            skip_ws()
            if i >= n or text[i] != '"':
                raise ValueError(f"expected string key at position {i}")
            key = parse_string()
            skip_ws()
            expect(":")
            obj[key] = parse_value()
            skip_ws()
            if i < n and text[i] == ",":
                i += 1
                continue
            expect("}")
            return obj

    value = parse_value()
    skip_ws()
    if i != n:
        raise ValueError(f"trailing data at position {i}")
    return value
```

Count how many words share each prefix (equivalent to trie node counts); a word's answer is its first prefix with count one, falling back to the whole word when every prefix is shared.
```python
from typing import List


def shortest_unique_prefixes(words: List[str]) -> List[str]:
    counts = {}
    for word in words:
        for i in range(1, len(word) + 1):
            prefix = word[:i]
            counts[prefix] = counts.get(prefix, 0) + 1
    result = []
    for word in words:
        chosen = word
        for i in range(1, len(word) + 1):
            if counts[word[:i]] == 1:
                chosen = word[:i]
                break
        result.append(chosen)
    return result
```

Anagrams share the same sorted-letter signature, so bucket words by that key in a dict, keep large-enough buckets, and sort within and across groups for a canonical output.
```python
def anagram_groups_min_size(words: list, min_size: int) -> list:
    groups = {}
    for word in words:
        groups.setdefault("".join(sorted(word)), []).append(word)
    result = [sorted(g) for g in groups.values() if len(g) >= min_size]
    return sorted(result, key=lambda g: g[0])
```

Apply the next-permutation algorithm to the digit string: find the rightmost ascent, swap its left element with the smallest larger digit to its right, and reverse the suffix. A fully non-increasing string has no successor.
```python
def next_digit_permutation(n: int) -> int:
    digits = list(str(n))
    i = len(digits) - 2
    while i >= 0 and digits[i] >= digits[i + 1]:
        i -= 1
    if i < 0:
        return -1
    j = len(digits) - 1
    while digits[j] <= digits[i]:
        j -= 1
    digits[i], digits[j] = digits[j], digits[i]
    digits[i + 1:] = reversed(digits[i + 1:])
    return int("".join(digits))
```

Map each priority value to its index and give all other values a single shared rank past the end; Python's stable sort then keeps the non-priority items in their original order.
```python
from typing import List


def priority_then_original_order(items: List[str], priority: List[str]) -> List[str]:
    rank = {}
    for i, value in enumerate(priority):
        rank.setdefault(value, i)
    fallback = len(priority)
    return sorted(items, key=lambda v: rank.get(v, fallback))
```

Validate the givens, then backtrack over empty cells in row-major order trying values in ascending order with row and column sets for O(1) conflict checks; the first completion found in this order is the lexicographically smallest.
```python
from typing import Optional


def complete_latin_square(grid: list[list[int]]) -> Optional[list[list[int]]]:
    n = len(grid)
    board = [row[:] for row in grid]
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]
    empties = []
    for r in range(n):
        for c in range(n):
            v = board[r][c]
            if v == 0:
                empties.append((r, c))
            elif v in row_used[r] or v in col_used[c]:
                return None
            else:
                row_used[r].add(v)
                col_used[c].add(v)

    def solve(k: int) -> bool:
        if k == len(empties):
            return True
        r, c = empties[k]
        for v in range(1, n + 1):
            if v not in row_used[r] and v not in col_used[c]:
                board[r][c] = v
                row_used[r].add(v)
                col_used[c].add(v)
                if solve(k + 1):
                    return True
                row_used[r].discard(v)
                col_used[c].discard(v)
                board[r][c] = 0
        return False

    return board if solve(0) else None
```

Classic divide and conquer: split by x, recurse on halves, then only points within sqrt(best) of the dividing line can do better, and scanning that strip in y-order needs only a constant number of comparisons per point; merging y-sorted halves keeps it O(n log n).
```python
from typing import List, Tuple


def closest_pair_squared_distance(points: List[Tuple[int, int]]) -> int:
    if len(points) < 2:
        return -1
    by_x = sorted(points)

    def solve(pts):
        # pts is sorted by x; returns (best, pts sorted by y)
        n = len(pts)
        if n <= 3:
            best = min(
                (pts[i][0] - pts[j][0]) ** 2 + (pts[i][1] - pts[j][1]) ** 2
                for i in range(n) for j in range(i + 1, n)
            ) if n >= 2 else float('inf')
            return best, sorted(pts, key=lambda p: p[1])
        mid = n // 2
        mid_x = pts[mid][0]
        best_left, left_y = solve(pts[:mid])
        best_right, right_y = solve(pts[mid:])
        best = min(best_left, best_right)
        merged = []
        i = j = 0
        while i < len(left_y) and j < len(right_y):
            if left_y[i][1] <= right_y[j][1]:
                merged.append(left_y[i]); i += 1
            else:
                merged.append(right_y[j]); j += 1
        merged.extend(left_y[i:])
        merged.extend(right_y[j:])
        strip = [p for p in merged if (p[0] - mid_x) ** 2 < best]
        for a in range(len(strip)):
            for b in range(a + 1, len(strip)):
                dy = strip[b][1] - strip[a][1]
                if dy * dy >= best:
                    break
                d = (strip[a][0] - strip[b][0]) ** 2 + dy * dy
                if d < best:
                    best = d
        return best, merged

    return solve(by_x)[0]
```

Use orientation signs from cross products: segments properly cross when each straddles the other's line, and every touching or collinear case reduces to some endpoint being collinear with and inside the other segment's bounding box.
```python
from typing import Tuple


def closed_segments_intersect(p1: Tuple[int, int], p2: Tuple[int, int],
                              p3: Tuple[int, int], p4: Tuple[int, int]) -> bool:
    def orient(a, b, c):
        v = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
        return (v > 0) - (v < 0)

    def on_segment(a, b, c):
        return (min(a[0], b[0]) <= c[0] <= max(a[0], b[0])
                and min(a[1], b[1]) <= c[1] <= max(a[1], b[1]))

    d1 = orient(p3, p4, p1)
    d2 = orient(p3, p4, p2)
    d3 = orient(p1, p2, p3)
    d4 = orient(p1, p2, p4)
    if d1 * d2 < 0 and d3 * d4 < 0:
        return True
    if d1 == 0 and on_segment(p3, p4, p1):
        return True
    if d2 == 0 and on_segment(p3, p4, p2):
        return True
    if d3 == 0 and on_segment(p1, p2, p3):
        return True
    if d4 == 0 and on_segment(p1, p2, p4):
        return True
    return False
```

Track the length of the current run of identical samples alongside the output state, and flip the output only when a differing value's run reaches k.
```python
def debounce_signal(samples: list[int], k: int) -> list[int]:
    out = []
    state = None
    run_value = None
    run_length = 0
    for s in samples:
        if s == run_value:
            run_length += 1
        else:
            run_value, run_length = s, 1
        if state is None:
            state = s
        elif s != state and run_length >= k:
            state = s
        out.append(state)
    return out
```

Breadth-first search from the start explores cells in order of distance, so the first time the target is dequeued its recorded distance is minimal.
```python
from collections import deque
from typing import List


def shortest_open_path_length(grid: List[str]) -> int:
    if not grid or not grid[0]:
        return -1
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[rows - 1][cols - 1] == '#':
        return -1
    dist = {(0, 0): 0}
    queue = deque([(0, 0)])
    while queue:
        r, c = queue.popleft()
        if (r, c) == (rows - 1, cols - 1):
            return dist[(r, c)]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in dist:
                dist[(nr, nc)] = dist[(r, c)] + 1
                queue.append((nr, nc))
    return -1
```

By inclusion-exclusion over square divisors, the count is sum over d <= sqrt(n) of mu(d) * floor(n / d^2); sieve the Mobius function up to sqrt(n) and add the terms.
```python
from math import isqrt


def count_squarefree_up_to(n: int) -> int:
    if n <= 0:
        return 0
    root = isqrt(n)
    mobius = [1] * (root + 1)
    is_composite = bytearray(root + 1)
    for p in range(2, root + 1):
        if not is_composite[p]:
            for multiple in range(p, root + 1, p):
                if multiple > p:
                    is_composite[multiple] = 1
                mobius[multiple] = -mobius[multiple]
            for multiple in range(p * p, root + 1, p * p):
                mobius[multiple] = 0
    return sum(mobius[d] * (n // (d * d)) for d in range(1, root + 1) if mobius[d])
```

