If a substring of length L repeats then so does one of length L-1, so binary search on the length; for each candidate length, a hash map of windows detects a repeat and the earliest first-occurrence among repeated windows resolves ties.
```python
def longest_repeated_substring(text: str) -> str:
    def find_repeat(length):
        seen = {}
        best = None
        for i in range(len(text) - length + 1):
            piece = text[i:i + length]
            if piece in seen:
                first = seen[piece]
                if best is None or first < best:
                    best = first
            else:
                seen[piece] = i
        return best

    lo, hi = 1, len(text) - 1
    best_start, best_len = 0, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        start = find_repeat(mid)
        if start is not None:
            best_start, best_len = start, mid
            lo = mid + 1
        else:
            hi = mid - 1
    return text[best_start:best_start + best_len]
```

Split on '&' before decoding so encoded separators like %26 or %3D stay inside values, partition each pair on the first '=', and decode both sides with unquote_plus. setdefault builds the per-name value lists.
```python
from urllib.parse import unquote_plus


def parse_query_string(query: str) -> dict[str, list[str]]:
    if query.startswith("?"):
        query = query[1:]
    result: dict[str, list[str]] = {}
    for pair in query.split("&"):
        if not pair:
            continue
        name, _, value = pair.partition("=")
        result.setdefault(unquote_plus(name), []).append(unquote_plus(value))
    return result
```

Split each name into alternating text and digit runs with a capturing regex; map digit runs to integers and text to casefolded strings, wrapping each in a tagged tuple so comparisons are always type-safe.
```python
import re
from typing import List


def natural_sort_filenames(names: List[str]) -> List[str]:
    def key(name: str):
        parts = re.split(r"(\d+)", name)
        # Even indices are text, odd indices are digit runs.
        chunks = tuple((0, int(p), "") if i % 2 else (1, 0, p.casefold())
                       for i, p in enumerate(parts))
        return (chunks, name)

    return sorted(names, key=key)
```

First compile the pattern into single-character matchers (literal, any, or character set) plus collapsed '*' markers, which isolates the fiddly bracket rules. Then run the classic two-pointer wildcard algorithm: remember the most recent star and, on a mismatch, let it absorb one more character, which keeps matching at O(m*n) worst case.
```python
def glob_match(pattern: str, text: str) -> bool:
    # Compile the pattern into single-character elements and '*' markers.
    elements: list[tuple] = []
    i, n = 0, len(pattern)
    while i < n:
        ch = pattern[i]
        if ch == "*":
            if not elements or elements[-1] != ("*",):
                elements.append(("*",))
            i += 1
        elif ch == "?":
            elements.append(("?",))
            i += 1
        elif ch == "[":
            j = i + 1
            negate = j < n and pattern[j] == "!"
            if negate:
                j += 1
            start = j
            if j < n and pattern[j] == "]":
                j += 1
            while j < n and pattern[j] != "]":
                j += 1
            if j >= n:
                elements.append(("lit", "["))
                i += 1
                continue
            body = pattern[start:j]
            members = []
            k = 0
            while k < len(body):
                if k + 2 < len(body) and body[k + 1] == "-":
                    members.append((body[k], body[k + 2]))
                    k += 3
                else:
                    members.append((body[k], body[k]))
                    k += 1
            elements.append(("set", negate, members))
            i = j + 1
        else:
            elements.append(("lit", ch))
            i += 1

    def matches_one(element: tuple, c: str) -> bool:
        kind = element[0]
        if kind == "?":
            return True
        if kind == "lit":
            return element[1] == c
        _, negate, members = element
        return any(lo <= c <= hi for lo, hi in members) != negate

    # Greedy match with backtracking to the most recent star: O(len(p) * len(t)).
    p = t = 0
    star_p, star_t = -1, 0
    while t < len(text):
        if p < len(elements) and elements[p][0] == "*":
            star_p, star_t = p, t
            p += 1
        elif p < len(elements) and matches_one(elements[p], text[t]):
            p += 1
            t += 1
        elif star_p != -1:
            star_t += 1
            t = star_t
            p = star_p + 1
        else:
            return False
    while p < len(elements) and elements[p][0] == "*":
        p += 1
    return p == len(elements)
```

A king can close both coordinate gaps simultaneously with diagonal moves, so the answer is the larger of the two absolute differences.
```python
from typing import Tuple


def chebyshev_distance(p: Tuple[int, int], q: Tuple[int, int]) -> int:
    return max(abs(p[0] - q[0]), abs(p[1] - q[1]))
```

Walk the characters accumulating the current word, and flush it whenever an uppercase letter arrives and the buffer is non-empty. Flush the final buffer at the end.
```python
def split_camel_case(name: str) -> list[str]:
    words: list[str] = []
    current = ""
    for ch in name:
        if ch.isupper() and current:
            words.append(current)
            current = ch
        else:
            current += ch
    if current:
        words.append(current)
    return words
```

Sort the positions and binary search on the answer: a gap is feasible if greedily taking the leftmost spot and then each next spot at least gap away yields count picks. Feasibility is monotone, so we search for the largest feasible gap.
```python
from typing import List


def widest_minimum_gap_placement(spots: List[int], count: int) -> int:
    pos = sorted(spots)

    def fits(gap: int) -> bool:
        placed, last = 1, pos[0]
        for p in pos[1:]:
            if p - last >= gap:
                placed += 1
                last = p
                if placed >= count:
                    return True
        return placed >= count

    lo, hi = 0, pos[-1] - pos[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if fits(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
```

Pad with 1s and do interval DP choosing which balloon k is popped last inside the open interval (left, right); its neighbours at that moment are exactly the interval ends.
```python
from typing import List


def max_coins_popping_balloons(balloons: List[int]) -> int:
    vals = [1] + list(balloons) + [1]
    n = len(vals)
    dp = [[0] * n for _ in range(n)]
    for width in range(2, n):
        for left in range(n - width):
            right = left + width
            dp[left][right] = max(
                dp[left][k] + vals[left] * vals[k] * vals[right] + dp[k][right]
                for k in range(left + 1, right)
            )
    return dp[0][n - 1]
```

Color vertices in index order and, for each, try every color that differs from its already-colored (lower-index) neighbours, backtracking and summing completions; self-loops are rejected up front.
```python
def count_proper_colorings(n: int, edges: list[tuple[int, int]], k: int) -> int:
    earlier_neighbors = [set() for _ in range(n)]
    for u, v in edges:
        if u == v:
            return 0
        a, b = (u, v) if u < v else (v, u)
        earlier_neighbors[b].add(a)
    color = [-1] * n

    def assign(vertex: int) -> int:
        if vertex == n:
            return 1
        total = 0
        for c in range(k):
            if all(color[u] != c for u in earlier_neighbors[vertex]):
                color[vertex] = c
                total += assign(vertex + 1)
        color[vertex] = -1
        return total

    return assign(0)
```

Iterate over lines remembering the last header name so continuation lines can be folded into it. Header lines are partitioned on the first colon (so values like times keep their colons), and duplicates are merged with ', '.
```python
import re


def parse_http_headers(raw: str) -> dict[str, str]:
    headers: dict[str, str] = {}
    last: str | None = None
    for line in re.split(r"\r?\n", raw):
        if not line.strip():
            continue
        if line[0] in " \t":
            if last is None:
                raise ValueError("continuation line without a preceding header")
            headers[last] = f"{headers[last]} {line.strip()}"
            continue
        name, sep, value = line.partition(":")
        if not sep:
            raise ValueError(f"malformed header line: {line!r}")
        name, value = name.strip().lower(), value.strip()
        headers[name] = f"{headers[name]}, {value}" if name in headers else value
        last = name
    return headers
```

Binary search on the answer between the largest chapter and the total; feasibility of a daily limit is checked greedily by packing chapters into a day until the next would overflow.
```python
from typing import List


def min_pages_per_reading_day(chapter_pages: List[int], days: int) -> int:
    if not chapter_pages:
        return 0

    def days_needed(limit: int) -> int:
        used, current = 1, 0
        for p in chapter_pages:
            if current + p > limit:
                used += 1
                current = 0
            current += p
        return used

    lo, hi = max(chapter_pages), sum(chapter_pages)
    while lo < hi:
        mid = (lo + hi) // 2
        if days_needed(mid) <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo
```

Sort by width ascending and, for equal widths, height descending so two boxes of the same width can never both be chosen; the problem then reduces to the longest strictly increasing subsequence of heights, solved with patience sorting and bisect_left.
```python
from bisect import bisect_left
from typing import List, Tuple


def longest_strictly_nested_boxes(boxes: List[Tuple[int, int]]) -> int:
    ordered = sorted(boxes, key=lambda b: (b[0], -b[1]))
    tails: List[int] = []
    for _, h in ordered:
        i = bisect_left(tails, h)
        if i == len(tails):
            tails.append(h)
        else:
            tails[i] = h
    return len(tails)
```

A three-state machine where the active modes only release at the midpoint, giving hysteresis; evaluate exactly one transition per reading and record the resulting mode.
```python
def thermostat_modes(temps: list[int], low: int, high: int) -> list[str]:
    mid = (low + high) // 2
    mode = "idle"
    out = []
    for t in temps:
        if mode == "idle":
            if t < low:
                mode = "heat"
            elif t > high:
                mode = "cool"
        elif mode == "heat":
            if t >= mid:
                mode = "idle"
        elif t <= mid:
            mode = "idle"
        out.append(mode)
    return out
```

Encode legal transitions in a (state, event) table, treat reset as a global edge back to CLOSED, and map every missing entry to an absorbing ERROR state.
```python
def tcp_like_state(events: list[str]) -> str:
    table = {
        ("CLOSED", "listen"): "LISTEN",
        ("LISTEN", "syn"): "SYN_RCVD",
        ("SYN_RCVD", "ack"): "ESTABLISHED",
        ("ESTABLISHED", "close"): "FIN_WAIT",
        ("FIN_WAIT", "ack"): "CLOSED",
    }
    state = "CLOSED"
    for event in events:
        if state == "ERROR":
            break
        if event == "reset":
            state = "CLOSED"
        else:
            state = table.get((state, event), "ERROR")
    return state
```

The light is periodic with period green + yellow + red, so reduce t modulo the period and compare the offset against the cumulative phase boundaries.
```python
def traffic_light_state(green: int, yellow: int, red: int, t: int) -> str:
    phase = t % (green + yellow + red)
    if phase < green:
        return "green"
    if phase < green + yellow:
        return "yellow"
    return "red"
```

Walk the string tracking the length of the current vowel streak, resetting on any non-vowel and recording the maximum seen.
```python
def longest_vowel_run(text: str) -> int:
    best = current = 0
    for ch in text:
        if ch.lower() in "aeiou":
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best
```

Depth-first explore knight moves while remembering the most moves left with which each cell was reached; revisiting a cell with no more budget than before cannot reach anything new, which prunes the search.
```python
def knight_squares_within_moves(n: int, start: tuple[int, int], k: int) -> int:
    jumps = ((1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1))
    best_remaining = {}

    def explore(r: int, c: int, remaining: int) -> None:
        if best_remaining.get((r, c), -1) >= remaining:
            return
        best_remaining[(r, c)] = remaining
        if remaining == 0:
            return
        for dr, dc in jumps:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                explore(nr, nc, remaining - 1)

    explore(start[0], start[1], k)
    return len(best_remaining)
```

Digit DP over the decimal digits of limit with state (position, remaining sum, tight flag); tight tracks whether the prefix still equals limit's prefix and caps the next digit. Leading zeros are harmless because they add nothing to the sum.
```python
from functools import lru_cache


def count_with_digit_sum(limit: int, target: int) -> int:
    if target < 0:
        return 0
    digits = list(map(int, str(limit)))

    @lru_cache(maxsize=None)
    def go(pos: int, remaining: int, tight: bool) -> int:
        if remaining < 0:
            return 0
        if pos == len(digits):
            return 1 if remaining == 0 else 0
        top = digits[pos] if tight else 9
        return sum(go(pos + 1, remaining - d, tight and d == top) for d in range(top + 1))

    return go(0, target, True)
```

Rebuild the list element by element: sublists are rebuilt recursively and leaf values are swapped when they equal old, so the original is never mutated.
```python
def replace_in_nested_list(data: list, old, new) -> list:
    return [
        replace_in_nested_list(item, old, new) if isinstance(item, list)
        else (new if item == old else item)
        for item in data
